function SpotlightBanner({ events }) {
  const scrollRef = React.useRef(null);

  const scroll = (direction) => {
    if (scrollRef.current) {
      const scrollAmount = 870; // width + gap
      scrollRef.current.scrollBy({ left: direction === 'left' ? -scrollAmount : scrollAmount, behavior: 'smooth' });
    }
  };

  return (
    <div style={{ position: 'relative', width: '100%' }}>
      <div ref={scrollRef} style={{ display: 'flex', gap: '24px', overflowX: 'auto', scrollbarWidth: 'none', paddingBottom: '20px', scrollSnapType: 'x mandatory' }}>
        {events.map((evt, idx) => (
          <div key={idx} style={{
            minWidth: '850px',
            width: '850px',
            height: '268px',
            backgroundColor: '#FFF1F2',
            borderRadius: '24px',
            display: 'flex',
            alignItems: 'center',
            padding: '24px',
            boxSizing: 'border-box',
            position: 'relative',
            flexShrink: 0,
            scrollSnapAlign: 'start',
            boxShadow: '0 4px 12px rgba(0,0,0,0.05)'
          }}>
            {/* Left Image Section */}
            <div style={{
              width: '58%',
              height: '100%',
              borderRadius: '16px',
              overflow: 'hidden',
              position: 'relative',
              backgroundColor: '#000'
            }}>
              <img
                src={evt.image}
                alt="Spotlight Event"
                style={{ width: '100%', height: '100%', objectFit: 'cover' }}
              />
            </div>

            {/* Right Content Section */}
            <div style={{ paddingLeft: '32px', flex: 1, color: '#111827' }}>
              <h3 style={{ fontSize: '20px', fontWeight: 800, marginBottom: '16px', textOverflow: 'ellipsis', overflow: 'hidden', whiteSpace: 'nowrap' }}>
                {evt.title}
              </h3>

              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#f43f5e', fontSize: '13px', fontWeight: 600, marginBottom: '12px' }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10" /><polyline points="12 6 12 12 16 14" /></svg>
                Event Starts In
              </div>

              <div style={{ display: 'flex', gap: '10px', marginBottom: '16px' }}>
                {[
                  { val: evt.eventStartsIn.days, label: 'DAYS' },
                  { val: evt.eventStartsIn.hours, label: 'HOURS' },
                  { val: evt.eventStartsIn.mins, label: 'MINS' },
                  { val: evt.eventStartsIn.secs, label: 'SECS' }
                ].map((timeBlock, i) => (
                  <div key={`${timeBlock.label}-${i}`} style={{ background: '#fff', border: '1px solid #ffe4e6', borderRadius: '8px', padding: '8px', width: '48px', textAlign: 'center' }}>
                    <div style={{ fontSize: '16px', fontWeight: 800 }}>{timeBlock.val}</div>
                    <div style={{ fontSize: '9px', fontWeight: 600, color: '#64748b' }}>{timeBlock.label}</div>
                  </div>
                ))}
              </div>

              <div style={{ display: 'flex', gap: '12px', marginBottom: '12px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '12px', fontWeight: 500, background: '#fff', border: '1px solid #ffe4e6', padding: '6px 12px', borderRadius: '50px' }}>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#f43f5e" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2" /><line x1="16" y1="2" x2="16" y2="6" /><line x1="8" y1="2" x2="8" y2="6" /><line x1="3" y1="10" x2="21" y2="10" /></svg>
                  {evt.date}
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '12px', fontWeight: 500, background: '#fff', border: '1px solid #ffe4e6', padding: '6px 12px', borderRadius: '50px' }}>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#f43f5e" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10" /><polyline points="12 6 12 12 16 14" /></svg>
                  {evt.time}
                </div>
              </div>

              <div style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', fontSize: '12px', fontWeight: 500, background: '#fff', border: '1px solid #ffe4e6', padding: '6px 12px', borderRadius: '50px', marginBottom: '16px' }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#f43f5e" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" /><circle cx="12" cy="10" r="3" /></svg>
                {evt.location}
              </div>
              <br />

              <button style={{ background: 'linear-gradient(to right, #fb923c, #f43f5e)', color: '#fff', border: 'none', padding: '8px 24px', borderRadius: '8px', fontSize: '14px', fontWeight: 700, cursor: 'pointer', zIndex: 10, position: 'relative' }}>
                Book Now
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Navigation Arrows */}
      <div style={{ position: 'absolute', top: '50%', right: '10px', transform: 'translateY(-50%)', display: 'flex', gap: '10px', zIndex: 20 }}>
        <button onClick={() => scroll('left')} style={{ width: '36px', height: '36px', borderRadius: '50%', background: '#fff', border: '1px solid #eaeaea', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: '#111827', boxShadow: '0 4px 6px rgba(0,0,0,0.1)' }}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6" /></svg>
        </button>
        <button onClick={() => scroll('right')} style={{ width: '36px', height: '36px', borderRadius: '50%', background: '#fff', border: '1px solid #eaeaea', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: '#111827', boxShadow: '0 4px 6px rgba(0,0,0,0.1)' }}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6" /></svg>
        </button>
      </div>

    </div>
  );
}

